/**
 * Single source of truth for the circuity color scale.
 *
 * The map (MapView) colors route lines by this scale and the Explore panel
 * renders its legend from the same stops, so legend and map can never drift.
 * Kept as one pure module with no React or Leaflet dependencies.
 */

export const CIRCUITY_SCALE: { value: number; rgb: [number, number, number] }[] = [
  { value: 1.0, rgb: [0, 200, 83] }, // #00C853 green
  { value: 1.2, rgb: [0, 200, 83] }, // green plateau
  { value: 1.5, rgb: [249, 168, 37] }, // #F9A825 golden — dark enough to read on light OSM tiles
  { value: 1.8, rgb: [239, 108, 0] }, // #EF6C00 deep orange
  { value: 3.0, rgb: [211, 47, 47] }, // #D32F2F red
  { value: 4.0, rgb: [127, 0, 0] }, // #7F0000 dark red
  { value: 5.0, rgb: [26, 26, 26] }, // near-black
];

export const CIRCUITY_MIN = CIRCUITY_SCALE[0].value;
export const CIRCUITY_MAX = CIRCUITY_SCALE[CIRCUITY_SCALE.length - 1].value;

function fmt(rgb: [number, number, number]): string {
  return `rgb(${rgb[0]},${rgb[1]},${rgb[2]})`;
}

/** Piecewise-interpolated color for a circuity ratio (length / straight-line). */
export function circuityColor(c: number): string {
  if (!isFinite(c)) return fmt(CIRCUITY_SCALE[CIRCUITY_SCALE.length - 1].rgb);
  if (c <= CIRCUITY_MIN) return fmt(CIRCUITY_SCALE[0].rgb);
  if (c >= CIRCUITY_MAX) return fmt(CIRCUITY_SCALE[CIRCUITY_SCALE.length - 1].rgb);
  for (let i = 0; i < CIRCUITY_SCALE.length - 1; i++) {
    const a = CIRCUITY_SCALE[i];
    const b = CIRCUITY_SCALE[i + 1];
    if (c >= a.value && c <= b.value) {
      const t = (c - a.value) / (b.value - a.value);
      const r = Math.round(a.rgb[0] + t * (b.rgb[0] - a.rgb[0]));
      const g = Math.round(a.rgb[1] + t * (b.rgb[1] - a.rgb[1]));
      const bl = Math.round(a.rgb[2] + t * (b.rgb[2] - a.rgb[2]));
      return `rgb(${r},${g},${bl})`;
    }
  }
  return fmt(CIRCUITY_SCALE[CIRCUITY_SCALE.length - 1].rgb);
}

/** CSS linear-gradient with stops placed at the real circuity values, so
 * legend buckets line up with the map's coloring. */
export const CIRCUITY_GRADIENT = `linear-gradient(90deg, ${CIRCUITY_SCALE.map((s) => {
  const pct = ((s.value - CIRCUITY_MIN) / (CIRCUITY_MAX - CIRCUITY_MIN)) * 100;
  return `rgb(${s.rgb[0]},${s.rgb[1]},${s.rgb[2]}) ${pct.toFixed(2)}%`;
}).join(', ')})`;
