import { useState } from 'react';
import { Activity, Bus, CheckCircle2, ChevronDown, Clock, Download, Loader2, Play, TrendingDown, TrendingUp } from 'lucide-react';
import type { OptimizeResponse } from '../types';
import type { VolumeMode } from '../lib/persist';

/**
 * Guided "Improve transfers" wizard. Breaks the workflow into numbered steps
 * so a first-time user knows exactly what to do: pick a day → choose how busy
 * → tweak timing → run → see results. The time-of-day period is chosen once in
 * the header, not repeated here.
 */

interface Props {
  maxShift: number;
  setMaxShift: (v: number) => void;
  bufferMinutes: number;
  setBufferMinutes: (v: number) => void;
  highFreqCutoff: number;
  setHighFreqCutoff: (v: number) => void;
  tMax: number;
  setTMax: (v: number) => void;
  minLayoverMinutes: number;
  setMinLayoverMinutes: (v: number) => void;
  timeLimitSeconds: number;
  setTimeLimitSeconds: (v: number) => void;
  serviceDay: 'weekday' | 'saturday' | 'sunday';
  volumeMode: VolumeMode;
  setVolumeMode: (v: VolumeMode) => void;
  running: boolean;
  onRun: () => void;
  result: OptimizeResponse | null;
  onExport: () => void;
  onPlannerReport: () => void;
  /** Label of the time-of-day the current result was computed for. */
  resultPeriodLabel: string | null;
  /** Label of the time-of-day currently selected in the header. */
  currentPeriodLabel: string;
  /** Service day the current result was computed for (null if never run). */
  resultServiceDay: 'weekday' | 'saturday' | 'sunday' | null;
}

/**
 * The weighting schemes the backend accepts (routers validate against
 * ``^(uniform|estimated|measured|ridership)$``). ``measured`` is deliberately
 * NOT offered here: its data file (``boardings_by_route.csv``) doesn't exist,
 * so the mode silently falls back to frequency weights, and the load-
 * reconstruction CSVs (``boardings_routes.csv``) are PM-rush lower bounds,
 * not daily boardings — wiring them in would be a different kind of lie.
 * ``ridership`` is the honest real-data option (APC figures for every route).
 * Labels are written for a general reader — the scheme's name is jargon,
 * what it *does* is not.
 */
const VOLUME_MODES: { value: string; label: string }[] = [
  { value: 'estimated', label: 'Estimated (busy routes count more)' },
  { value: 'uniform', label: 'Equal (every route counts the same)' },
  { value: 'ridership', label: 'Real ridership (most accurate)' },
];

function StepNumber({ n }: { n: number }) {
  return (
    <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-optimized/15 text-[11px] font-bold text-optimized">
      {n}
    </span>
  );
}

function Slider({
  label,
  value,
  min,
  max,
  step,
  unit,
  onChange,
  hint,
}: {
  label: string;
  value: number;
  min: number;
  max: number;
  step: number;
  unit: string;
  onChange: (v: number) => void;
  hint: string;
}) {
  return (
    <label className="block">
      <div className="flex items-baseline justify-between gap-2">
        <span className="text-xs font-medium text-text-secondary">{label}</span>
        <span className="rounded bg-card-hover px-1.5 py-0.5 text-xs font-semibold text-optimized">
          {value}
          {unit}
        </span>
      </div>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={value}
        onChange={(e) => onChange(Number(e.target.value))}
        className="mt-1 w-full accent-optimized"
      />
      <span className="block text-[10px] leading-snug text-text-muted">{hint}</span>
    </label>
  );
}

function Metric({
  icon,
  label,
  value,
  sub,
  plain,
  tone,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
  sub: string;
  plain?: string;
  tone: 'optimized' | 'bottleneck' | 'accent';
}) {
  const color =
    tone === 'optimized' ? 'text-optimized' : tone === 'bottleneck' ? 'text-bottleneck' : 'text-accent';
  return (
    <div className="rounded-xl border border-border bg-card p-3">
      <div className="flex items-center gap-2 text-text-secondary">
        <span className={color}>{icon}</span>
        <span className="text-[11px] font-medium">{label}</span>
      </div>
      <div className="mt-1 text-lg font-bold text-text-primary">{value}</div>
      <div className="text-[10px] leading-snug text-text-muted">{sub}</div>
      {plain ? <div className="mt-0.5 text-[10px] leading-snug text-text-secondary italic">{plain}</div> : null}
    </div>
  );
}

export default function OptimizePanel({
  maxShift,
  setMaxShift,
  bufferMinutes,
  setBufferMinutes,
  highFreqCutoff,
  setHighFreqCutoff,
  tMax,
  setTMax,
  minLayoverMinutes,
  setMinLayoverMinutes,
  timeLimitSeconds,
  setTimeLimitSeconds,
  serviceDay,
  volumeMode,
  setVolumeMode,
  running,
  onRun,
  result,
  onExport,
  onPlannerReport,
  resultPeriodLabel,
  currentPeriodLabel,
  resultServiceDay,
}: Props) {
  const fleetFeasibility = result?.fleet_feasibility ?? null;
  // The timing sliders are real knobs, but a first-time user shouldn't have to
  // understand them. They default to sensible values, so they're collapsed
  // behind "Advanced timing rules" and only opened on purpose.
  const [showAdvanced, setShowAdvanced] = useState(false);
  // A result from a previous period/day is easy to mistake for the current
  // selection — flag it so nobody reads a stale run as this period's answer.
  // Provenance unknown (null) counts as stale too: better to warn than to
  // silently present a run the user can't attribute.
  const staleResult =
    result != null &&
    (resultServiceDay == null ||
      resultPeriodLabel == null ||
      resultPeriodLabel !== currentPeriodLabel ||
      resultServiceDay !== serviceDay);

  return (
    <div className="flex flex-col gap-3">
      {/* A22 (2026-09-27): the primary action leads the panel. The old order
          (intro card → One Fare banner → weighting dropdown → Run) left the
          button mid-card and below first paint at 390px; a first-time user
          read prose and hunted. One name everywhere: the sidebar/tab say
          "Fix transfers", so the button does too. */}
      <button
        onClick={onRun}
        disabled={running}
        className="inline-flex w-full items-center justify-center gap-2 rounded-lg bg-optimized px-4 py-3 text-sm font-bold text-bg transition-colors hover:brightness-110 disabled:cursor-not-allowed disabled:opacity-60"
      >
        {running ? <Loader2 className="h-4 w-4 animate-spin" /> : <Play className="h-4 w-4" />}
        {running ? 'Optimizing…' : 'Fix transfers'}
      </button>

      <section className="rounded-xl border border-border bg-card p-3">
        <div className="flex items-center gap-2 text-xs font-semibold text-text-secondary">
          <Activity className="h-4 w-4 text-accent" />
          Improve transfers
        </div>
        <p className="mt-1.5 text-[11px] leading-snug text-text-muted">
          Shifts bus departure times so riders wait less when switching buses. Defaults are sensible — the button above runs it as-is.
        </p>
        <div className="mt-2 rounded-lg border border-optimized/20 bg-optimized/5 px-2.5 py-1.5 text-[10px] text-optimized">
          <span className="font-semibold">One Fare:</span> MiWay transfers to GO Transit are free via PRESTO — optimizing these connections saves riders real money.
        </div>
      </section>

      {/* step 1: volume mode */}
      <section className="rounded-xl border border-border bg-card p-3">
        <div className="mb-1.5 flex items-center gap-2">
          <StepNumber n={1} />
          <span className="text-xs font-semibold text-text-primary">How important is each route?</span>
        </div>
        <select
          aria-label="Ridership weighting"
          value={volumeMode}
          onChange={(e) => setVolumeMode(e.target.value as VolumeMode)}
          className="w-full rounded-lg border border-border bg-card-hover px-2.5 py-1.5 text-xs font-semibold text-text-primary outline-none transition-colors focus:border-accent"
        >
          {VOLUME_MODES.map((m) => (
            <option key={m.value} value={m.value}>
              {m.label}
            </option>
          ))}
        </select>
        <p className="mt-1.5 text-[10px] leading-snug text-text-muted">
          Estimated counts busy routes more. Real ridership uses APC data. Source: MiWay 2024 Report to the Community — may be outdated.
        </p>
      </section>

      {/* (A22) Run moved to the top of the panel; this comment marks the old
          slot so the {result?.updated_stop_times_available} export buttons
          stay tied to the results context below. */}
      {result?.updated_stop_times_available && (
        <button
          onClick={onExport}
          className="inline-flex w-full items-center justify-center gap-2 rounded-lg border border-border px-3 py-2 text-xs font-semibold text-text-secondary transition-colors hover:bg-card-hover"
        >
          <Download className="h-4 w-4" />
          Export updated GTFS schedule
        </button>
      )}
      {result && (
        <button
          onClick={onPlannerReport}
          className="inline-flex w-full items-center justify-center gap-2 rounded-lg border border-border px-3 py-2 text-xs font-semibold text-text-secondary transition-colors hover:bg-card-hover"
        >
          <Download className="h-4 w-4" />
          Download planner report (CSV)
        </button>
      )}

      {/* step 2: timing rules */}
      <section className="rounded-xl border border-border bg-card p-3">
        <button
          type="button"
          onClick={() => setShowAdvanced((v) => !v)}
          className="flex w-full items-center gap-2 text-left"
          aria-expanded={showAdvanced}
        >
          <StepNumber n={2} />
          <span className="text-xs font-semibold text-text-primary">Fine-tune the timing (optional)</span>
          <span className="ml-auto text-[10px] text-text-muted">
            {showAdvanced ? 'Hide' : 'Advanced'}
          </span>
          <ChevronDown
            className={`h-3.5 w-3.5 text-text-muted transition-transform ${showAdvanced ? 'rotate-180' : ''}`}
          />
        </button>
        {!showAdvanced ? null : (
          <>
            <p className="mt-2 text-xs leading-snug text-text-muted">
              How closely should buses line up, and how long may the optimizer think? The defaults
              work well — change these only if you know why.
            </p>
            <div className="mt-3 flex flex-col gap-4">
              <Slider
                label="How far schedules can move"
                value={maxShift}
                min={1}
                max={15}
                step={1}
                unit=" min"
                onChange={setMaxShift}
                hint="The most a route's times may shift to line up connections."
              />
              <Slider
                label="Cushion between buses"
                value={bufferMinutes}
                min={0}
                max={10}
                step={1}
                unit=" min"
                onChange={setBufferMinutes}
                hint="Minimum gap between a bus arriving and the next one leaving."
              />
              <Slider
                label="Leave frequent routes alone"
                value={highFreqCutoff}
                min={1}
                max={30}
                step={1}
                unit=" min"
                onChange={setHighFreqCutoff}
                hint="Routes running this often (or more) are not changed."
              />
              <Slider
                label="Longest wait to accept"
                value={tMax}
                min={1}
                max={30}
                step={1}
                unit=" min"
                onChange={setTMax}
                hint="The longest wait the optimizer will keep a connection for."
              />
              <Slider
                label="Rest time between trips"
                value={minLayoverMinutes}
                min={0}
                max={30}
                step={1}
                unit=" min"
                onChange={setMinLayoverMinutes}
                hint="Time for the same bus and driver to rest before its next trip."
              />
              <Slider
                label="How long the optimizer may think"
                value={timeLimitSeconds}
                min={5}
                max={300}
                step={5}
                unit=" s"
                onChange={setTimeLimitSeconds}
                hint="More time can give a better result but makes the run slower."
              />
            </div>
          </>
        )}
      </section>



      {/* results */}
      {staleResult && (
        <div className="rounded-xl border bg-amber-500/10 p-3 text-[11px] leading-snug text-amber-400">
          These results are from <b>{resultPeriodLabel}</b> ·{' '}
          <span className="capitalize">{resultServiceDay}</span> — the current selection is{' '}
          <b>{currentPeriodLabel}</b> · <span className="capitalize">{serviceDay}</span>. Re-run to
          match.
        </div>
      )}
      {result && result.passenger_minutes_saved === 0 && (
        <div className="rounded-xl border bg-amber-500/10 p-3 text-[11px] leading-snug text-amber-400">
          No net improvement for <b>{currentPeriodLabel}</b> ·{' '}
          <span className="capitalize">{serviceDay}</span> — shifting a route to help
          one time of day tends to hurt another, so the whole-day window washes out.
          Try a narrower window (<b>AM Rush</b> or <b>Late Night</b>) to see real wins.
        </div>
      )}
      {result && (
        <section className="rounded-xl border bg-card p-4">
          <div className="mb-3 flex items-center gap-2 text-xs font-semibold text-optimized">
            <CheckCircle2 className="h-4 w-4" />
            Results
            {result.status === 'OPTIMAL' ? (
              <span
                title="The solver proved this schedule is within 6% of the best achievable — running longer cannot meaningfully improve it."
                className="rounded-full bg-optimized/10 px-2 py-0.5 text-[10px] font-semibold normal-case text-optimized"
              >
                provably optimal{result.solve_duration_seconds ? ` · ${result.solve_duration_seconds.toFixed(0)}s solve` : ''}
              </span>
            ) : (
              <span
                title={
                  result.bound_gap_pct != null
                    ? `The solve hit its time budget with a good schedule. Its answer is provably within ${result.bound_gap_pct}% of the best possible — that's the most a longer run could add.`
                    : 'The solve hit its time budget with a good schedule, but a longer run might still find improvements. Re-running with a higher time limit can certify optimality.'
                }
                className="rounded-full bg-amber-500/10 px-2 py-0.5 text-[10px] font-semibold normal-case text-amber-400"
              >
                within {result.bound_gap_pct != null ? `${result.bound_gap_pct}%` : '?'} of best{result.solve_duration_seconds ? ` · ${result.solve_duration_seconds.toFixed(0)}s solve` : ''}
              </span>
            )}
            {result.solver_variance_pct != null && (
              <span
                title="FEASIBLE solves are non-deterministic. Across identical-config runs, network passenger-minutes saved varies ±1% (ward/stop level varies more). This is the estimated run-to-run spread."
                className="rounded-full bg-amber-500/10 px-2 py-0.5 text-[10px] font-semibold normal-case text-amber-400"
              >
                run variance ±{result.solver_variance_pct}%
              </span>
            )}
            {resultPeriodLabel && resultServiceDay && (
              <span className="ml-auto rounded-full bg-optimized/10 px-2 py-0.5 text-[10px] font-semibold normal-case text-optimized">
                {resultPeriodLabel} · {resultServiceDay}
              </span>
            )}
          </div>
          <div className="grid grid-cols-1 gap-2">
            <Metric
              icon={<TrendingDown className="h-4 w-4" />}
              label="Passenger-minutes saved"
              value={running ? '…' : result.passenger_minutes_saved.toFixed(0)}
              sub="total wait time removed for riders"
              plain="That's like giving every rider on the midday network a couple of extra minutes of their day back."
              tone="optimized"
            />
            <Metric
              icon={<Activity className="h-4 w-4" />}
              label="Transfers that work"
              value={running ? '…' : `${result.connection_health.toFixed(0)}%`}
              sub={`${result.total_kept} of ${result.total_connections} transfers meet the wait target`}
              plain="The rest are waits no schedule shift can fix — they need more service or a different routing."
              tone="accent"
            />
            <Metric
              icon={<Clock className="h-4 w-4" />}
              label="Average wait"
              value={
                running
                  ? '…'
                  : `${result.baseline_avg_wait.toFixed(1)} → ${result.optimized_avg_wait.toFixed(1)} min`
              }
              sub={`missed connections: ${result.baseline_missed} → ${result.optimized_missed}`}
              plain="A missed connection means the rider waits a full bus interval for the next departure."
              tone="bottleneck"
            />
          </div>
          {fleetFeasibility && (
            <div className="mt-3 rounded-lg border border-border bg-bg p-3">
              <div className="flex items-center gap-2 text-[11px] font-semibold text-text-secondary">
                <Bus className="h-3.5 w-3.5" />
                Fleet feasibility
              </div>
              <div className="mt-1 text-[10px] leading-snug text-text-muted">
                {fleetFeasibility.interlining_edges} vehicle block hand-offs · layover violations{' '}
                {fleetFeasibility.baseline_violations} → {fleetFeasibility.optimized_violations} (min{' '}
                {fleetFeasibility.min_layover_minutes} min)
                {fleetFeasibility.block_aware ? ' · block-aware' : ''}
              </div>
              {fleetFeasibility.detail && (
                <div className="mt-1 text-[10px] leading-snug text-text-muted">{fleetFeasibility.detail}</div>
              )}
            </div>
          )}
          {result.route_impacts && result.route_impacts.length > 0 && (
            <div className="mt-3 rounded-lg border border-border bg-bg p-3">
              <div className="flex items-center gap-2 text-[11px] font-semibold text-text-secondary">
                <TrendingUp className="h-3.5 w-3.5" />
                Route-by-route impact
              </div>
              <p className="mt-1 text-[10px] leading-snug text-text-muted">
                Weighted change in passenger-facing wait per route (negative = riders wait less).{' '}
                Routes in red have connections where some riders now wait longer.
              </p>
              <div className="mt-2 max-h-56 space-y-1 overflow-y-auto pr-1">
                {result.route_impacts.map((r) => (
                  <div
                    key={r.route_short_name}
                    className="flex items-center justify-between gap-2 rounded-lg bg-card-hover/60 px-2 py-1.5"
                  >
                    <div className="min-w-0">
                      <span className="text-[11px] font-bold text-text-primary">Route {r.route_short_name}</span>
                      {r.route_long_name && (
                        <span className="ml-1.5 text-[10px] text-text-muted">{r.route_long_name}</span>
                      )}
                    </div>
                    <div className="flex shrink-0 items-center gap-2">
                      {r.worse_off && (
                        <span className="rounded bg-red-500/15 px-1.5 py-0.5 text-[10px] font-semibold text-red-400">
                          {r.worse_off_connections} worse · +{r.worse_off_max_minutes.toFixed(1)} min
                        </span>
                      )}
                      <span
                        className={`text-[11px] font-bold ${ r.delta_minutes <= 0 ? 'text-optimized' : 'text-red-400' }`}
                      >
                        {r.delta_minutes > 0 ? '+' : ''}
                        {r.delta_minutes.toFixed(2)} min
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
          <p className="mt-3 text-[10px] leading-snug text-text-muted">
            The charts below show the full picture. Use the map layers to inspect the new schedule.
          </p>
        </section>
      )}

      {!result && (
        <p className="px-1 text-[10px] leading-snug text-text-muted">
          Tip: results appear here and in the charts below after you run an optimization.
        </p>
      )}
    </div>
  );
}
