import { useMemo } from 'react';
import { AlertTriangle, ArrowRight, GitBranch, Info, Layers, Ruler } from 'lucide-react';
import type { CircuityGeoJSON, CircuitySummaryRoute, RouteFeature } from '../types';
import BeforeAfterMiniMap from './BeforeAfterMiniMap';
import { PROPOSED_DEFAULT_COLOR, routePalette } from '../lib/mapLayers';
import NewHereHint from './NewHereHint';

/**
 * Route-quality panel: flagged winding routes and how direct they are. The
 * full trunk + branch split proposals live in their own Trunk & feeder tab;
 * here the map stays focused on today's routing — with an optional overlay of
 * the proposed splits and a before/after mini-map for the worst offenders.
 */

interface Props {
  flaggedRoutes: CircuitySummaryRoute[];
  threshold: number;
  highlightedRoute: string | null;
  onHighlight: (routeShortName: string | null) => void;
  /** Full circuity FeatureCollection (needed for the proposed-split overlay + mini-maps). */
  circuity?: CircuityGeoJSON | null;
  showSplits?: boolean;
  setShowSplits?: (v: boolean) => void;
  /** Jump to the dedicated trunk + branch split tab. */
  onOpenTrunkFeeder?: () => void;
}

/** Worst N flagged routes that have a proposed split, by circuity. */
function topOffenders(circuity: CircuityGeoJSON | null | undefined, n: number): RouteFeature[] {
  if (!circuity) return [];
  return circuity.features
    .filter((f) => f.properties.flagged && f.properties.proposed_split)
    .sort((a, b) => b.properties.circuity - a.properties.circuity)
    .slice(0, n);
}

export default function CircuityPanel({
  flaggedRoutes,
  threshold,
  highlightedRoute,
  onHighlight,
  circuity,
  showSplits = false,
  setShowSplits,
  onOpenTrunkFeeder,
}: Props) {
  const offenders = useMemo(() => topOffenders(circuity, 5), [circuity]);
  const palette = useMemo(
    () => routePalette(offenders.map((f) => f.properties.route_short_name)),
    [offenders]
  );

  if (flaggedRoutes.length === 0) {
    return (
      <div className="rounded-xl border border-optimized/40 bg-card p-4 text-sm text-text-muted">
        <div className="flex items-center gap-2 text-xs font-semibold text-optimized">
          <Info className="h-4 w-4" />
          No winding routes found
        </div>
        <p className="mt-2 text-[11px] leading-relaxed">
          No routes travel more than {threshold.toFixed(1)}× their straight-line distance. Your
          network is in good shape.
        </p>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-3">
      {/* newcomer hint ---------------------------------------------------- */}
      <NewHereHint text="Green lines are near-straight; red lines wander. Click a route to highlight it on the map and see its exact directness score." />

      {/* optional proposed-split overlay toggle --------------------------- */}
      {setShowSplits && (
        <button
          onClick={() => setShowSplits(!showSplits)}
          className={`flex items-center gap-2 rounded-xl border px-4 py-3 text-left text-xs font-semibold transition-colors ${ showSplits ? 'border-accent/50 bg-accent/15 text-accent' : 'border-border bg-card text-text-secondary hover:bg-card-hover' }`}
        >
          <GitBranch className="h-4 w-4 shrink-0" />
          <span className="min-w-0">
            <span className="block">
              {showSplits
                ? 'Showing proposed trunk + feeder splits on the map'
                : 'Show proposed trunk + feeder splits on the map'}
            </span>
            <span className="mt-0.5 block text-[10px] font-normal text-text-muted">
              {showSplits
                ? 'Today’s routing stays underneath — toggle off to return to directness only.'
                : 'Overlay the proposed splits on top of today’s directness map.'}
            </span>
          </span>
        </button>
      )}

      {/* winding routes list ---------------------------------------------- */}
      <section className="rounded-xl border border-border bg-card p-4">
        <div className="flex items-center gap-2 text-xs font-semibold text-text-secondary">
          <AlertTriangle className="h-4 w-4 text-danger" />
          Routes that take the long way
        </div>
        <p className="mt-1 text-[11px] leading-relaxed text-text-muted">
          These routes travel a lot farther than a straight line between their ends. Click one to
          see it on the map.
        </p>
        <ul className="mt-3 space-y-1.5">
          {flaggedRoutes.map((r) => (
            <li
              key={r.route_id}
              onClick={() =>
                onHighlight(highlightedRoute === r.route_short_name ? null : r.route_short_name)
              }
              className={`flex cursor-pointer items-center justify-between rounded-lg px-2.5 py-1.5 text-xs transition-colors ${ highlightedRoute === r.route_short_name ? 'bg-bottleneck/15 ring-1 ring-bottleneck' : 'bg-card-hover hover:bg-border' }`}
            >
              <span className="font-medium text-text-primary">
                Route {r.route_short_name}
                {r.route_long_name ? (
                  <span className="ml-1.5 text-[10px] text-text-muted">{r.route_long_name}</span>
                ) : null}
              </span>
              <span className="flex items-center gap-2">
                <span className="flex items-center gap-1 text-text-muted">
                  <Ruler className="h-3 w-3" />
                  {r.length_km.toFixed(1)} km
                </span>
                <span className="w-16 text-right font-semibold text-bottleneck">
                  {r.circuity.toFixed(2)}×
                </span>
              </span>
            </li>
          ))}
        </ul>
      </section>

      {/* before/after mini-maps for the worst offenders ------------------- */}
      {offenders.length > 0 && (
        <section className="rounded-xl border border-border bg-card p-4">
          <div className="flex items-center gap-2 text-xs font-semibold text-text-secondary">
            <Layers className="h-4 w-4 text-accent" />
            Before / after — worst offenders
          </div>
          <p className="mt-1 text-[11px] leading-relaxed text-text-muted">
            Today’s winding routing (gray dashed) vs the proposed trunk (solid) + feeders (dashed
            in the same color). Click a card to see it on the big map.
          </p>
          <div className="mt-3 space-y-3">
            {offenders.map((f) => {
              const p = f.properties;
              const split = p.proposed_split!;
              const color = palette.get(p.route_short_name) ?? PROPOSED_DEFAULT_COLOR;
              const feederKm = split.branches.reduce((s, b) => s + b.length_km, 0);
              const feederN = split.branches.length;
              const selected = highlightedRoute === p.route_short_name;
              return (
                <button
                  key={p.route_id}
                  onClick={() => onHighlight(selected ? null : p.route_short_name)}
                  className={`w-full rounded-lg p-2.5 text-left transition-colors ${ selected ? 'bg-accent/15 ring-1 ring-accent' : 'bg-card-hover hover:bg-border' }`}
                >
                  <div className="flex items-center justify-between gap-2">
                    <span className="min-w-0 truncate text-xs font-semibold text-text-primary">
                      Route {p.route_short_name}
                      {p.route_long_name ? (
                        <span className="ml-1.5 text-[10px] font-normal text-text-muted">
                          {p.route_long_name}
                        </span>
                      ) : null}
                    </span>
                    <span className="shrink-0 text-[10px] text-text-muted">
                      <span className="font-semibold text-bottleneck">
                        {p.circuity.toFixed(2)}×
                      </span>
                      <ArrowRight className="mx-1 inline h-3 w-3" />
                      <span className="font-semibold text-optimized">
                        {split.trunk_circuity.toFixed(2)}×
                      </span>
                    </span>
                  </div>
                  <div className="mt-1.5">
                    <BeforeAfterMiniMap
                      coords={f.geometry.coordinates as [number, number][]}
                      trunkCoords={split.trunk_geometry}
                      branchCoords={split.branches.map((b) => b.geometry)}
                      color={color}
                    />
                  </div>
                  <div className="mt-1 flex items-center justify-between gap-2 text-[10px] text-text-muted">
                    <span>{p.length_km.toFixed(1)} km today</span>
                    <span className="truncate">
                      {split.trunk_length_km.toFixed(1)} km trunk
                      {feederN > 0
                        ? ` + ${feederKm.toFixed(1)} km feeder${feederN > 1 ? 's' : ''}`
                        : ''}
                    </span>
                  </div>
                </button>
              );
            })}
          </div>
        </section>
      )}

      {onOpenTrunkFeeder && (
        <button
          onClick={onOpenTrunkFeeder}
          className="flex items-center justify-between rounded-xl border border-accent/40 bg-accent/10 px-4 py-3 text-left transition-colors hover:bg-accent/20"
        >
          <span>
            <span className="flex items-center gap-2 text-xs font-semibold text-text-primary">
              <GitBranch className="h-4 w-4 text-accent" />
              Want to split one of these?
            </span>
            <span className="mt-0.5 block text-[10px] text-text-muted">
              See the proposed trunk + branch splits in the Trunk &amp; feeder tab.
            </span>
          </span>
        </button>
      )}
    </div>
  );
}
