import { TimerReset, TrendingUp, Users, Wallet } from 'lucide-react';
import type { OptimizeResponse } from '../types';
import NewHereHint from './NewHereHint';

/**
 * "Projected ridership impact" — a separate, self-contained section that turns
 * the optimizer's wait-time savings into an expected ridership gain using
 * published elasticities (methodology + sources rendered in the footnote).
 */

interface Props {
  result: OptimizeResponse | null;
}

function Metric({
  icon,
  label,
  value,
  sub,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
  sub: string;
}) {
  return (
    <div className="rounded-xl border border-border bg-bg p-3">
      <div className="flex items-center gap-2 text-text-secondary">
        <span className="text-optimized">{icon}</span>
        <span className="text-[11px] font-medium">{label}</span>
      </div>
      <div className="mt-1 text-lg font-bold text-text-primary">{value}</div>
      <div className="text-[10px] leading-snug text-text-muted">{sub}</div>
    </div>
  );
}

export default function RidershipImpact({ result }: Props) {
  const r = result?.ridership_impact;
  if (!r) {
    return null;
  }

  return (
    <section className="rounded-xl border border-border bg-card p-4">
      <div className="flex items-center gap-2 text-sm font-semibold text-text-primary">
        <TrendingUp className="h-4 w-4 text-optimized" />
        Projected ridership impact
      </div>
      <p className="mt-1 text-[11px] text-text-muted">
        What the wait-time savings are worth to riders — with no new buses or drivers.
      </p>

      <div className="mt-3">
        <NewHereHint text="These numbers are estimates based on published research. The methodology note at the bottom explains how they were calculated." />
      </div>

      <div className="mt-3 grid grid-cols-1 gap-2 min-[420px]:grid-cols-2 sm:grid-cols-4">
        <Metric
          icon={<TimerReset className="h-4 w-4" />}
          label="Wait saved"
          value={`${r.wait_minutes_saved.toFixed(1)} min`}
          sub={`${r.wait_time_premium}× premium applied (waiting counts more than riding)`}
        />
        <Metric
          icon={<Wallet className="h-4 w-4" />}
          label="Rider time value"
          value={`${r.ivt_equivalent_minutes.toFixed(1)} min`}
          sub={`equivalent in-vehicle minutes per trip`}
        />
        <Metric
          icon={<TimerReset className="h-4 w-4" />}
          label="Trip time cut"
          value={`${r.travel_time_reduction_pct.toFixed(1)}%`}
          sub={`of an assumed ${r.avg_trip_minutes.toFixed(0)}-min trip`}
        />
        <Metric
          icon={<Users className="h-4 w-4" />}
          label="Ridership gain"
          value={`+${r.projected_ridership_pct.toFixed(1)}%`}
          sub={
            r.projected_ridership_pct_min != null && r.projected_ridership_pct_max != null
              ? `plausible band +${r.projected_ridership_pct_min.toFixed(1)}–${r.projected_ridership_pct_max.toFixed(1)}% · elasticity ${r.travel_time_elasticity} (Dowling 2005)`
              : `elasticity ${r.travel_time_elasticity} (Dowling 2005)`
          }
        />
      </div>

      <p className="mt-3 text-[10px] leading-relaxed text-text-muted">
        {r.methodology}
      </p>
      <p className="mt-1 text-[10px] leading-relaxed text-text-muted">
        Sources: Pratt (1999) &amp; Evans (2004) in TCRP Report 95; Litman,
        “Valuing Transit Service Quality Improvements” &amp; “Transit Price
        Elasticities” (VTPI) — waiting is valued 2–5× in-vehicle time. Dowling
        Associates (2005, Portland) — travel-time elasticity ≈ −0.13. Estimates
        vary by corridor; treat as an order-of-magnitude projection.
      </p>
    </section>
  );
}
