import { useMemo } from 'react';
import { HelpCircle, Layers, MapPin, Ruler } from 'lucide-react';
import type { CircuityGeoJSON } from '../types';
import {
  circuityColor,
  CIRCUITY_GRADIENT,
  CIRCUITY_MAX,
  CIRCUITY_MIN,
} from '../lib/circuityColor';
import type { MapEngine } from './MapView';
import NewHereHint from './NewHereHint';

/**
 * Side panel for the "Explore" tab: layer toggles, the circuity color legend,
 * and a route-highlight dropdown. Keeps jargon out and explains each layer.
 * Legend colors come from lib/circuityColor — the same scale the map draws with.
 */

const LEGEND_TICKS = [
  { v: 1.0, label: '1.0×' },
  { v: 1.5, label: '1.5×' },
  { v: 2.0, label: '2.0×' },
  { v: 3.0, label: '3.0×' },
  { v: 5.0, label: '5.0×' },
];

/** One row per real scale segment, swatch colored at the segment midpoint. */
const CIRCUITY_KEYS: { mid: number; label: string }[] = [
  { mid: 1.1, label: '1.0–1.2× · near straight' },
  { mid: 1.35, label: '1.2–1.5× · slightly winding' },
  { mid: 1.65, label: '1.5–1.8× · winding' },
  { mid: 2.4, label: '1.8–3.0× · very winding' },
  { mid: 3.5, label: '3.0–4.0× · extremely winding' },
  { mid: 4.5, label: '4.0–5.0× · most roundabout' },
];

interface Props {
  circuity: CircuityGeoJSON | null;
  showRoutes: boolean;
  setShowRoutes: (v: boolean) => void;
  showSplits: boolean;
  setShowSplits: (v: boolean) => void;
  showNodes: boolean;
  setShowNodes: (v: boolean) => void;
  showOneWay: boolean;
  setShowOneWay: (v: boolean) => void;
  mapEngine: MapEngine;
  setMapEngine: (v: MapEngine) => void;
  highlightedRoute: string | null;
  setHighlightedRoute: (v: string | null) => void;
}

function Toggle({
  checked,
  onChange,
  label,
  desc,
  accent,
}: {
  checked: boolean;
  onChange: (v: boolean) => void;
  label: string;
  desc: string;
  accent: string;
}) {
  return (
    <label className="flex cursor-pointer items-start gap-2 rounded-lg bg-card-hover px-2.5 py-2 transition-colors hover:bg-border">
      <input
        type="checkbox"
        checked={checked}
        onChange={(e) => onChange(e.target.checked)}
        className={`mt-0.5 ${accent}`}
      />
      <span>
        <span className="block text-xs font-semibold text-text-primary">{label}</span>
        <span className="block text-[10px] leading-snug text-text-muted">{desc}</span>
      </span>
    </label>
  );
}

export default function ExplorePanel({
  circuity,
  showRoutes,
  setShowRoutes,
  showSplits,
  setShowSplits,
  showNodes,
  setShowNodes,
  showOneWay,
  setShowOneWay,
  mapEngine,
  setMapEngine,
  highlightedRoute,
  setHighlightedRoute,
}: Props) {
  const routeOptions = useMemo(() => {
    type Entry = { route_id: string; route_short_name: string; circuity: number; flagged: boolean };
    if (!circuity) return { flagged: [] as Entry[], rest: [] as Entry[] };
    const byRoute = new Map<string, Entry>();
    for (const f of circuity.features) {
      const key = f.properties.route_short_name;
      const p = f.properties;
      const prev = byRoute.get(key);
      if (!prev) {
        byRoute.set(key, {
          route_id: p.route_id,
          route_short_name: key,
          circuity: p.circuity,
          flagged: p.flagged,
        });
      } else {
        prev.circuity = Math.max(prev.circuity, p.circuity);
        prev.flagged = prev.flagged || p.flagged;
        if (p.proposed_split) prev.route_id = p.route_id;
      }
    }
    const all = [...byRoute.values()];
    const flagged = all
      .filter((r) => r.flagged)
      .sort((a, b) => b.circuity - a.circuity)
      .slice(0, 20);
    const rest = all
      .filter((r) => !r.flagged)
      .sort((a, b) =>
        a.route_short_name.localeCompare(b.route_short_name, undefined, {
          numeric: true,
          sensitivity: 'base',
        })
      );
    return { flagged, rest };
  }, [circuity]);

  return (
    <div className="flex flex-col gap-3">
      {/* what you're looking at */}
      <section className="rounded-xl border border-border bg-card p-4">
        <div className="flex items-center gap-2 text-xs font-semibold text-text-secondary">
          <HelpCircle className="h-4 w-4 text-accent" />
          What you&apos;re looking at
        </div>
        <p className="mt-2 text-[11px] leading-relaxed text-text-muted">
          This map shows every MiWay route in the network. Lines are colored by{' '}
          <span className="text-text-primary" title="Directness = how close a route is to a straight line between its ends. 1.0× = perfect, 2.0× = twice as long as needed.">directness</span> — how close the route is to a
          straight line between its ends. Pick any route in the list below to highlight it on the
          map.
        </p>
      </section>

      {/* newcomer hint ---------------------------------------------------- */}
      <NewHereHint text="Green = near-straight route, red = winding. Use the dropdown below to highlight any route on the map." />

      {/* layers */}
      <section className="rounded-xl border border-border bg-card p-4">
        <div className="mb-2 flex items-center gap-2 text-xs font-semibold text-text-secondary">
          <Layers className="h-4 w-4 text-accent" />
          Map layers
        </div>
        <div className="flex flex-col gap-1.5">
          <Toggle
            checked={showRoutes}
            onChange={setShowRoutes}
            label="Bus routes"
            desc="Every route on the map, colored by directness (green = near-straight, red = winding)."
            accent="accent-optimized"
          />
          <Toggle
            checked={showSplits}
            onChange={setShowSplits}
            label="Suggested route splits"
            desc="Draw each proposed trunk (solid) + branch (dashed) in its own color on the map."
            accent="accent-bottleneck"
          />
          <Toggle
            checked={showNodes}
            onChange={setShowNodes}
            label="Busy transfer stops"
            desc="Show transfer stops dot-colored by friction score (green < 20, amber 20–30, red > 30). Visible once you zoom in."
            accent="accent-accent"
          />
          <Toggle
            checked={showOneWay}
            onChange={setShowOneWay}
            label="One-way routes"
            desc="Purple dashed lines — routes that only run in one direction this period (common in rush hour)."
            accent="accent-bottleneck"
          />
        </div>
        <details className="mt-3 rounded-lg border border-border bg-card-hover/40 px-2.5 py-2">
          <summary className="cursor-pointer list-none text-xs font-semibold text-text-secondary">
            Advanced: map troubleshooting
          </summary>
          <label className="mt-2 flex items-center gap-1.5 text-xs text-text-secondary">
            Map engine:
            <select
              value={mapEngine}
              onChange={(e) => setMapEngine(e.target.value as MapEngine)}
              className="rounded-lg border border-border bg-card-hover px-2 py-1 text-xs text-text-secondary"
            >
              <option value="auto">Auto</option>
              <option value="leaflet">Leaflet</option>
              <option value="svg">SVG</option>
            </select>
          </label>
          <p className="mt-1.5 text-xs leading-snug text-text-muted">
            If the map looks blank, try switching the engine. Auto usually works.
          </p>
        </details>
      </section>

      {/* legend */}
      <section className="rounded-xl border border-border bg-card p-4">
        <div className="mb-2 flex items-center gap-2 text-xs font-semibold text-text-secondary">
          <Ruler className="h-4 w-4 text-accent" />
          Color legend
        </div>
        <div
          className="h-2 w-full rounded-full"
          style={{ background: CIRCUITY_GRADIENT }}
        />
        <div className="relative mt-0.5 h-3">
          {LEGEND_TICKS.map((t) => (
            <span
              key={t.v}
              className="absolute -translate-x-1/2 text-[9px] text-text-muted"
              style={{
                left: `${((t.v - CIRCUITY_MIN) / (CIRCUITY_MAX - CIRCUITY_MIN)) * 100}%`,
              }}
            >
              {t.label}
            </span>
          ))}
        </div>
        <div className="mt-1.5 grid grid-cols-2 gap-x-3 gap-y-1">
          {CIRCUITY_KEYS.map((k) => (
            <span key={k.label} className="flex items-center gap-1.5 text-[10px] text-text-secondary">
              <span
                className="h-2.5 w-2.5 shrink-0 rounded-full"
                style={{ background: circuityColor(k.mid) }}
              />
              {k.label}
            </span>
          ))}
        </div>
        <p className="mt-2 text-[10px] leading-snug text-text-muted">
          1.0× means the route is a straight line — 2.0× means it travels twice as far as needed.
          The bar uses the same scale as the colored lines on the map.
        </p>
      </section>

      {/* highlight dropdown */}
      {circuity && (
        <section className="rounded-xl border border-border bg-card p-4">
          <div className="mb-2 flex items-center gap-2 text-xs font-semibold text-text-secondary">
            <MapPin className="h-4 w-4 text-accent" />
            Highlight a route
          </div>
          <select
            value={highlightedRoute ?? ''}
            onChange={(e) => setHighlightedRoute(e.target.value || null)}
            className="w-full rounded-lg border border-border bg-card-hover px-2 py-1.5 text-xs text-text-secondary"
          >
            <option value="">Pick a route…</option>
            <optgroup label="Most winding">
              {routeOptions.flagged.map((f) => (
                <option key={f.route_id} value={f.route_short_name}>
                  Route {f.route_short_name} ({f.circuity.toFixed(2)}×)
                </option>
              ))}
            </optgroup>
            <optgroup label="All other routes">
              {routeOptions.rest.map((f) => (
                <option key={f.route_id} value={f.route_short_name}>
                  Route {f.route_short_name}
                </option>
              ))}
            </optgroup>
          </select>
          {routeOptions.flagged.length === 0 && routeOptions.rest.length === 0 && (
            <p className="mt-2 text-[10px] text-text-muted">No routes to highlight yet.</p>
          )}
        </section>
      )}
    </div>
  );
}
